{"solution_py":""""Resolve the CLI color mode during a flag migration."""
from __future__ import annotations

from collections.abc import Sequence


def parse_color_mode(argv: Sequence[str]) -> str:
    """Return the requested color mode, defaulting to ``auto``.

    Accepts ``--color MODE``, ``--color=MODE``, and the legacy
    ``--no-color`` flag. Unrelated arguments are ignored.
    """
    modes: list[str] = []
    valid_modes = {"auto", "always", "never"}
    i = 0

    while i < len(argv):
        arg = argv[i]
        if arg == "--no-color":
            modes.append("never")
        elif arg == "--color":
            i += 1
            if i >= len(argv) or argv[i].startswith("--"):
                raise ValueError("--color requires a mode: auto, always, or never")
            mode = argv[i]
            if mode not in valid_modes:
                raise ValueError(f"invalid color mode: {mode}")
            modes.append(mode)
        elif arg.startswith("--color="):
            mode = arg.partition("=")[2]
            if mode not in valid_modes:
                raise ValueError(f"invalid color mode: {mode}")
            modes.append(mode)
        i += 1

    if modes and any(mode != modes[0] for mode in modes[1:]):
        raise ValueError("conflicting color options")
    return modes[0] if modes else "auto"
